import type { FreeCamera } from "@babylonjs/lite";
import { createBankedFreeCamera } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };

export interface ChaseCamera {
  camera: FreeCamera;
  bank(up: Vec): void;
}

const EPS = 1e-7;
const UP0: Vec = { x: 0, y: 1, z: 0 };
const AXES: readonly Vec[] = [
  { x: 1, y: 0, z: 0 },
  { x: 0, y: 1, z: 0 },
  { x: 0, y: 0, z: 1 },
];

function finite(v: Vec): boolean { return Number.isFinite(v.x) && Number.isFinite(v.y) && Number.isFinite(v.z); }
function readVec(source: unknown): Vec | null { ... }
function writeVec(target: unknown, v: Vec): void { ... }
function dot(a,b) ...
function len(v) ...
function normalize(v): Vec | null { if (!finite(v)) return null; const l = len(v); if (l < EPS) return null; return {x:v.x/l,...}; }
function subtract(a,b) ...
function scale(v,s) ...
function orthogonalize(desired, forward): Vec | null {
 const d = dot(desired, forward);
 if (Math.abs(d) >= 1 - EPS) return null;
 const p = subtract(desired, scale(forward, d));
 return normalize(p);
}
function makePerpendicular(desired, forward): Vec | null {
 const p = orthogonalize(desired, forward); if (p) return p;
 for (const axis of AXES) { const q = orthogonalize(axis, forward); if (q) return q; }
 return null;
}
function currentForward(camera: FreeCamera): Vec | null { const pos = readVec((camera as any).position); const tgt = readVec((camera as any).target); if (!pos || !tgt) return null; return normalize(subtract(tgt,pos)); }

export function createChaseCamera(eye: Vec, target: Vec): ChaseCamera {
 const camera = createBankedFreeCamera(eye as any, target as any, UP0 as any) as FreeCamera;
 const upVector = (camera as any).upVector;
 let lastUp = UP0;
 const f0 = currentForward(camera);
 if (f0) { const initial = makePerpendicular(UP0, f0); if (initial) { lastUp = initial; writeVec(upVector, initial); } }
 function bank(up: Vec): void {
   const desired = normalize(up);
   if (!desired) return;
   const f = currentForward(camera);
   if (!f) return;
   const targetUp = orthogonalize(desired, f);
   if (targetUp) {
     lastUp = targetUp;
     writeVec(upVector, targetUp);
     return;
   }
   // Degenerate: requested up is parallel/anti-parallel. Keep previous roll.
   const previous = readVec(upVector);
   const previousNormalized = previous ? normalize(previous) : null;
   const reference = previousNormalized ?? lastUp;
   const preserved = orthogonalize(reference, f);
   if (!preserved) return;
   const current = normalize(readVec(upVector));
   if (!current || dot(current, preserved) < 1 - EPS) {
     lastUp = preserved;
     writeVec(upVector, preserved);
   }
 }
 return { camera, bank };
}
